package local.skyfamily;
import android.content.Context;import android.graphics.*;import android.view.View;
final class ControlIcon extends View {
 String label;Paint p=new Paint(3);ControlIcon(Context c,String text){super(c);label=text;}void label(String text){label=text;invalidate();}
 protected void onDraw(Canvas c){String s=label.toLowerCase(java.util.Locale.US);c.save();c.scale(getWidth()/32f,getHeight()/32f);p.setColor(0xffb2c9f5);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setStrokeCap(Paint.Cap.ROUND);if(s.contains("pause")){c.drawLine(11,7,11,25,p);c.drawLine(21,7,21,25,p);}else if(s.contains("play")||s.contains("start")){Path path=new Path();path.moveTo(10,6);path.lineTo(26,16);path.lineTo(10,26);path.close();c.drawPath(path,p);}else if(s.contains("previous")||s.equals("left")){c.drawLine(22,6,10,16,p);c.drawLine(10,16,22,26,p);}else if(s.contains("next")||s.equals("right")){c.drawLine(10,6,22,16,p);c.drawLine(22,16,10,26,p);}else if(s.contains("rotate")||s.contains("turn")||s.equals("screen")){c.drawArc(new RectF(5,5,27,27),-55,285,false,p);c.drawLine(26,5,26,13,p);c.drawLine(26,5,18,5,p);}else if(s.contains("full")||s.contains("fit")){for(int i=0;i<4;i++){c.save();c.rotate(i*90,16,16);c.drawLine(5,12,5,5,p);c.drawLine(5,5,12,5,p);c.restore();}}else if(s.contains("exit")||s.contains("forget")||s.contains("sign out")){c.drawLine(8,8,24,24,p);c.drawLine(24,8,8,24,p);}else if(s.contains("mute")){Path path=new Path();path.moveTo(5,13);path.lineTo(11,13);path.lineTo(18,7);path.lineTo(18,25);path.lineTo(11,19);path.lineTo(5,19);path.close();c.drawPath(path,p);if(s.contains("unmute")){c.drawLine(23,12,29,20,p);c.drawLine(29,12,23,20,p);}else c.drawArc(new RectF(16,7,30,25),-60,120,false,p);}else if(s.contains("save")||s.contains("export")){c.drawRoundRect(new RectF(5,4,27,28),3,3,p);c.drawRect(10,4,22,12,p);c.drawRect(10,19,22,28,p);}else if(s.contains("bookmark")){Path path=new Path();path.moveTo(9,4);path.lineTo(23,4);path.lineTo(23,28);path.lineTo(16,22);path.lineTo(9,28);path.close();c.drawPath(path,p);}else if(s.contains("undo")){c.drawArc(new RectF(7,9,27,27),190,255,false,p);c.drawLine(5,8,5,17,p);c.drawLine(5,17,14,17,p);}else if(s.contains("upload")||s.contains("receive")||s.contains("import")){c.drawLine(16,5,16,22,p);c.drawLine(9,12,16,5,p);c.drawLine(23,12,16,5,p);c.drawLine(5,22,5,28,p);c.drawLine(5,28,27,28,p);c.drawLine(27,28,27,22,p);}else if(s.contains("album")||s.contains("photo")||s.contains("media")){c.drawRoundRect(new RectF(4,7,28,27),3,3,p);c.drawLine(8,3,24,3,p);c.drawCircle(11,13,2,p);Path path=new Path();path.moveTo(6,24);path.lineTo(16,15);path.lineTo(26,24);c.drawPath(path,p);}else if(s.contains("tool")||s.contains("brush")){c.drawLine(7,25,25,7,p);c.drawLine(11,28,28,11,p);c.drawOval(new RectF(4,22,12,30),p);}else if(s.contains("selected")||s.contains("apply")){c.drawCircle(16,16,12,p);c.drawLine(9,16,14,21,p);c.drawLine(14,21,24,10,p);}else if(s.contains("page")||s.contains("book")||s.contains("library")){c.drawRoundRect(new RectF(5,4,27,28),3,3,p);c.drawLine(16,4,16,28,p);c.drawLine(9,11,12,11,p);c.drawLine(20,11,23,11,p);}else{c.drawRoundRect(new RectF(5,5,27,27),5,5,p);c.drawLine(10,12,22,12,p);c.drawLine(10,19,22,19,p);}c.restore();}
}
